import{_ as t,o as a,c as o,a0 as d}from"./chunks/framework.BhkMvQqH.js";const m=JSON.parse('{"title":"System Configuration Specification","description":"","frontmatter":{},"headers":[],"relativePath":"specs/system-config.md","filePath":"specs/system-config.md"}'),i={name:"specs/system-config.md"};function r(n,e,s,l,c,u){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="system-configuration-specification" tabindex="-1">System Configuration Specification <a class="header-anchor" href="#system-configuration-specification" aria-label="Permalink to &quot;System Configuration Specification&quot;">​</a></h1><h2 id="screen-system-exchange-rates" tabindex="-1">Screen: System Exchange Rates <a class="header-anchor" href="#screen-system-exchange-rates" aria-label="Permalink to &quot;Screen: System Exchange Rates&quot;">​</a></h2><h3 id="route" tabindex="-1">Route <a class="header-anchor" href="#route" aria-label="Permalink to &quot;Route&quot;">​</a></h3><p><code>/system/exchange-rates</code></p><h3 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h3><p>View official exchange rates auto-populated by a backend bot. Reference data for financial transactions — rates are frozen at transaction time, not read live from this table.</p><h3 id="data-source" tabindex="-1">Data Source <a class="header-anchor" href="#data-source" aria-label="Permalink to &quot;Data Source&quot;">​</a></h3><ul><li><strong>Table(s)</strong>: <code>SystemExchangeRate</code></li><li><strong>RLS Context</strong>: Tenant-scoped. RLS filters by tenant&#39;s primary/secondary currency pair. No write access.</li></ul><h3 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Source</th><th>Required</th><th>Editable</th><th>Notes</th></tr></thead><tbody><tr><td>From Currency</td><td>text</td><td><code>sys_exc_rate_from_currency</code></td><td>N/A</td><td>No</td><td>ISO 4217 (typically USD)</td></tr><tr><td>To Currency</td><td>text</td><td><code>sys_exc_rate_to_currency</code></td><td>N/A</td><td>No</td><td>ISO 4217</td></tr><tr><td>Rate Value</td><td>decimal(19,6)</td><td><code>sys_exc_rate_value</code></td><td>N/A</td><td>No</td><td>Up to 6 decimal places</td></tr><tr><td>Effective Date</td><td>date</td><td><code>sys_exc_rate_effective_date</code></td><td>N/A</td><td>No</td><td>Single day validity</td></tr><tr><td>Source</td><td>text</td><td><code>sys_exc_rate_source</code></td><td>N/A</td><td>No</td><td>e.g., &quot;BCV_OFFICIAL&quot;</td></tr></tbody></table><h3 id="actions-crud" tabindex="-1">Actions / CRUD <a class="header-anchor" href="#actions-crud" aria-label="Permalink to &quot;Actions / CRUD&quot;">​</a></h3><ul><li>[ ] Create (backend bot only)</li><li>[x] Read</li><li>[ ] Update (immutable by design)</li><li>[ ] Delete (immutable by design)</li><li>[ ] Special</li></ul><h3 id="related-selectors-modals" tabindex="-1">Related Selectors / Modals <a class="header-anchor" href="#related-selectors-modals" aria-label="Permalink to &quot;Related Selectors / Modals&quot;">​</a></h3><ul><li><strong>Currency filter</strong>: Filter rates by from-currency or to-currency.</li><li><strong>Date range picker</strong>: Filter by effective date range.</li></ul><h3 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h3><ul><li><strong>Module code</strong>: <code>CFG-001</code> (inferred)</li><li><strong>Minimum role permissions</strong>: read</li><li><strong>Special rules</strong>: RLS filters rows whose <code>from_currency</code> or <code>to_currency</code> matches <code>Organization.org_currency_primary</code> or <code>org_currency_secondary</code>. If <code>org_use_official_exchange_rate = false</code>, this screen still shows data but the org uses <code>org_custom_exchange_rate</code> instead.</li></ul><h3 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h3><ul><li><strong>Parent</strong>: System Configuration (menu group)</li><li><strong>Links to</strong>: None (view-only reference)</li></ul><h3 id="ux-pattern" tabindex="-1">UX Pattern <a class="header-anchor" href="#ux-pattern" aria-label="Permalink to &quot;UX Pattern&quot;">​</a></h3><p>List/Table with date filtering and currency filter</p><h3 id="business-rules-validations" tabindex="-1">Business Rules / Validations <a class="header-anchor" href="#business-rules-validations" aria-label="Permalink to &quot;Business Rules / Validations&quot;">​</a></h3><ul><li>Rates are append-only. No user can create, update, or delete rows (backend bot only).</li><li>A given currency pair MAY have multiple rates on different dates — the effective rate for a transaction is the one with <code>effective_date &lt;= transaction_date</code> ordered by most recent.</li><li>The <code>org_use_official_exchange_rate</code> flag on the Organization determines whether this table or <code>org_custom_exchange_rate</code> is used for financial calculations.</li><li>Table MUST be sorted by effective date descending by default.</li></ul><h3 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h3><p>This is purely a read-only reference. Financial screens (Expense, Payment) freeze the exchange rate at transaction creation time by copying the applicable rate into their own <code>exchange_rate_used</code> field. No live-linking needed.</p><hr><h2 id="screen-document-types" tabindex="-1">Screen: Document Types <a class="header-anchor" href="#screen-document-types" aria-label="Permalink to &quot;Screen: Document Types&quot;">​</a></h2><h3 id="route-1" tabindex="-1">Route <a class="header-anchor" href="#route-1" aria-label="Permalink to &quot;Route&quot;">​</a></h3><p><code>/system/document-types</code></p><h3 id="purpose-1" tabindex="-1">Purpose <a class="header-anchor" href="#purpose-1" aria-label="Permalink to &quot;Purpose&quot;">​</a></h3><p>View valid identity document types for the tenant&#39;s country. Used as reference data in employee and client forms.</p><h3 id="data-source-1" tabindex="-1">Data Source <a class="header-anchor" href="#data-source-1" aria-label="Permalink to &quot;Data Source&quot;">​</a></h3><ul><li><strong>Table(s)</strong>: <code>DocumentType</code></li><li><strong>RLS Context</strong>: <code>FOR SELECT USING (true)</code> — public read, but frontend SHOULD filter by tenant&#39;s country.</li></ul><h3 id="fields-1" tabindex="-1">Fields <a class="header-anchor" href="#fields-1" aria-label="Permalink to &quot;Fields&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Source</th><th>Required</th><th>Editable</th><th>Notes</th></tr></thead><tbody><tr><td>Code</td><td>text</td><td><code>doc_type_code</code></td><td>N/A</td><td>No</td><td>Abbreviation, e.g., &quot;V&quot; for Cédula</td></tr><tr><td>Name</td><td>text</td><td><code>doc_type_name</code></td><td>N/A</td><td>No</td><td>e.g., &quot;Cédula&quot;, &quot;Pasaporte&quot;</td></tr><tr><td>Country</td><td>text</td><td><code>doc_type_country</code></td><td>N/A</td><td>No</td><td>ISO 3166-1 alpha-2</td></tr></tbody></table><h3 id="actions-crud-1" tabindex="-1">Actions / CRUD <a class="header-anchor" href="#actions-crud-1" aria-label="Permalink to &quot;Actions / CRUD&quot;">​</a></h3><ul><li>[ ] Create (system-managed)</li><li>[x] Read</li><li>[ ] Update (system-managed)</li><li>[ ] Delete (system-managed)</li><li>[ ] Special</li></ul><h3 id="related-selectors-modals-1" tabindex="-1">Related Selectors / Modals <a class="header-anchor" href="#related-selectors-modals-1" aria-label="Permalink to &quot;Related Selectors / Modals&quot;">​</a></h3><ul><li>None (consumed as dropdown by Employee and Client forms)</li></ul><h3 id="permissions-1" tabindex="-1">Permissions <a class="header-anchor" href="#permissions-1" aria-label="Permalink to &quot;Permissions&quot;">​</a></h3><ul><li><strong>Module code</strong>: <code>CFG-001</code> (inferred, grouped with System Config)</li><li><strong>Minimum role permissions</strong>: read</li><li><strong>Special rules</strong>: Frontend MUST filter rows by <code>doc_type_country = org_country</code>. This is an application-level filter since the RLS policy allows all reads.</li></ul><h3 id="navigation-1" tabindex="-1">Navigation <a class="header-anchor" href="#navigation-1" aria-label="Permalink to &quot;Navigation&quot;">​</a></h3><ul><li><strong>Parent</strong>: System Configuration (menu group)</li><li><strong>Links to</strong>: None (reference data consumed by other screens)</li></ul><h3 id="ux-pattern-1" tabindex="-1">UX Pattern <a class="header-anchor" href="#ux-pattern-1" aria-label="Permalink to &quot;UX Pattern&quot;">​</a></h3><p>Reference table (read-only list)</p><h3 id="business-rules-validations-1" tabindex="-1">Business Rules / Validations <a class="header-anchor" href="#business-rules-validations-1" aria-label="Permalink to &quot;Business Rules / Validations&quot;">​</a></h3><ul><li>No user CRUD — this is system-seeded data maintained via DB migration or seed script.</li><li>Frontend MUST filter by the tenant&#39;s country (from <code>Organization.org_country</code>) when using as dropdown.</li><li>The dropdown shows: <code>&quot;Code — Name&quot;</code> format, e.g., <code>&quot;V — Cédula&quot;</code></li></ul><h3 id="notes-1" tabindex="-1">Notes <a class="header-anchor" href="#notes-1" aria-label="Permalink to &quot;Notes&quot;">​</a></h3><p>This is the simplest screen in the system. Only needed as a standalone screen for admin reference. In practice, most users will only interact with Document Types through selectors on Employee/Client forms, not this standalone page.</p><hr><h2 id="screen-system-payment-methods" tabindex="-1">Screen: System Payment Methods <a class="header-anchor" href="#screen-system-payment-methods" aria-label="Permalink to &quot;Screen: System Payment Methods&quot;">​</a></h2><h3 id="route-2" tabindex="-1">Route <a class="header-anchor" href="#route-2" aria-label="Permalink to &quot;Route&quot;">​</a></h3><p><code>/system/payment-methods</code></p><h3 id="purpose-2" tabindex="-1">Purpose <a class="header-anchor" href="#purpose-2" aria-label="Permalink to &quot;Purpose&quot;">​</a></h3><p>View available payment gateway types supported by the Bookia platform. Reference data for the Organization Payment Methods configuration screen.</p><h3 id="data-source-2" tabindex="-1">Data Source <a class="header-anchor" href="#data-source-2" aria-label="Permalink to &quot;Data Source&quot;">​</a></h3><ul><li><strong>Table(s)</strong>: <code>SystemPaymentMethod</code>, <code>SystemPaymentMethodCountry</code></li><li><strong>RLS Context</strong>: <code>FOR SELECT USING (true)</code> — public read. Frontend MUST filter by tenant&#39;s country and active status.</li></ul><h3 id="fields-2" tabindex="-1">Fields <a class="header-anchor" href="#fields-2" aria-label="Permalink to &quot;Fields&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Source</th><th>Required</th><th>Editable</th><th>Notes</th></tr></thead><tbody><tr><td>Method Code</td><td>text</td><td><code>sys_pay_meth_code</code></td><td>N/A</td><td>No</td><td>e.g., &quot;pago_movil&quot;, &quot;zelle&quot;</td></tr><tr><td>Name</td><td>text</td><td><code>sys_pay_meth_name</code></td><td>N/A</td><td>No</td><td>Display name</td></tr><tr><td>Status</td><td>badge</td><td><code>sys_pay_meth_status_code</code></td><td>N/A</td><td>No</td><td>1=Active, 0=Blocked</td></tr><tr><td>Countries</td><td>text[]</td><td><code>SystemPaymentMethodCountry</code> (joined)</td><td>N/A</td><td>No</td><td>Comma-separated list of ISO country codes</td></tr></tbody></table><h3 id="actions-crud-2" tabindex="-1">Actions / CRUD <a class="header-anchor" href="#actions-crud-2" aria-label="Permalink to &quot;Actions / CRUD&quot;">​</a></h3><ul><li>[ ] Create (system-managed)</li><li>[x] Read</li><li>[ ] Update (system-managed)</li><li>[ ] Delete (system-managed)</li><li>[ ] Special</li></ul><h3 id="related-selectors-modals-2" tabindex="-1">Related Selectors / Modals <a class="header-anchor" href="#related-selectors-modals-2" aria-label="Permalink to &quot;Related Selectors / Modals&quot;">​</a></h3><ul><li><strong>Country filter</strong>: Filter by tenant&#39;s country (default) or select a different country to preview.</li></ul><h3 id="permissions-2" tabindex="-1">Permissions <a class="header-anchor" href="#permissions-2" aria-label="Permalink to &quot;Permissions&quot;">​</a></h3><ul><li><strong>Module code</strong>: <code>CFG-001</code> (inferred, grouped with System Config)</li><li><strong>Minimum role permissions</strong>: read</li><li><strong>Special rules</strong>: RLS allows all reads; frontend filters by <code>sys_pay_meth_status_code = 1</code> AND existence in <code>SystemPaymentMethodCountry</code> for the tenant&#39;s country.</li></ul><h3 id="navigation-2" tabindex="-1">Navigation <a class="header-anchor" href="#navigation-2" aria-label="Permalink to &quot;Navigation&quot;">​</a></h3><ul><li><strong>Parent</strong>: System Configuration (menu group)</li><li><strong>Links to</strong>: Organization Payment Methods (parent config screen uses this as source)</li></ul><h3 id="ux-pattern-2" tabindex="-1">UX Pattern <a class="header-anchor" href="#ux-pattern-2" aria-label="Permalink to &quot;UX Pattern&quot;">​</a></h3><p>Reference list with country filter and status badges</p><h3 id="business-rules-validations-2" tabindex="-1">Business Rules / Validations <a class="header-anchor" href="#business-rules-validations-2" aria-label="Permalink to &quot;Business Rules / Validations&quot;">​</a></h3><ul><li>ONLY methods with <code>sys_pay_meth_status_code = 1</code> SHALL be shown in the default view.</li><li>Methods MUST have an entry in <code>SystemPaymentMethodCountry</code> for the tenant&#39;s country to be shown as &quot;available&quot;.</li><li>The Organization Payment Methods screen uses this table as its source for selecting which method to affiliate.</li><li>Methods with status = 0 (blocked) SHOULD be hidden from dropdowns in other screens but MAY appear here for admin reference.</li></ul><h3 id="notes-2" tabindex="-1">Notes <a class="header-anchor" href="#notes-2" aria-label="Permalink to &quot;Notes&quot;">​</a></h3><p>This data is typically stable — seeded at platform launch and rarely changed. The <code>SystemPaymentMethodCountry</code> join provides geographic segmentation (e.g., Zelle is US-only, Pago Móvil is Venezuela-only).</p><hr><h2 id="screen-plan-management" tabindex="-1">Screen: Plan Management <a class="header-anchor" href="#screen-plan-management" aria-label="Permalink to &quot;Screen: Plan Management&quot;">​</a></h2><h3 id="route-3" tabindex="-1">Route <a class="header-anchor" href="#route-3" aria-label="Permalink to &quot;Route&quot;">​</a></h3><p><code>/admin/plans</code></p><h3 id="purpose-3" tabindex="-1">Purpose <a class="header-anchor" href="#purpose-3" aria-label="Permalink to &quot;Purpose&quot;">​</a></h3><p>Create, edit, deactivate, and delete subscription plans. Super-admin only screen for managing the SaaS monetization catalog.</p><h3 id="data-source-3" tabindex="-1">Data Source <a class="header-anchor" href="#data-source-3" aria-label="Permalink to &quot;Data Source&quot;">​</a></h3><ul><li><strong>Table(s)</strong>: <code>Plan</code></li><li><strong>RLS Context</strong>: No RLS — restricted by admin API key or super-admin access only.</li></ul><h3 id="fields-3" tabindex="-1">Fields <a class="header-anchor" href="#fields-3" aria-label="Permalink to &quot;Fields&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Source</th><th>Required</th><th>Editable</th><th>Notes</th></tr></thead><tbody><tr><td>Name</td><td>text</td><td><code>pln_name</code></td><td>Yes</td><td>Yes</td><td>Commercial name, e.g., &quot;Plan Pro&quot;</td></tr><tr><td>Description</td><td>text</td><td><code>pln_description</code></td><td>No</td><td>Yes</td><td>Marketing text, nullable</td></tr><tr><td>Max Employees</td><td>number</td><td><code>pln_max_employees</code></td><td>No</td><td>Yes</td><td>NULL = unlimited</td></tr><tr><td>Max Clients</td><td>number</td><td><code>pln_max_clients</code></td><td>No</td><td>Yes</td><td>NULL = unlimited</td></tr><tr><td>Max Resources</td><td>number</td><td><code>pln_max_resources</code></td><td>No</td><td>Yes</td><td>CHECK &gt;= 0</td></tr><tr><td>Max Services</td><td>number</td><td><code>pln_max_services</code></td><td>No</td><td>Yes</td><td>CHECK &gt;= 0</td></tr><tr><td>Currency</td><td>select</td><td><code>pln_currency_code</code></td><td>Yes</td><td>Yes</td><td>ISO 4217</td></tr><tr><td>Monthly Price</td><td>decimal(10,2)</td><td><code>pln_monthly_price</code></td><td>Yes</td><td>Yes</td><td>&gt;= 0</td></tr><tr><td>Annual Price</td><td>decimal(10,2)</td><td><code>pln_annual_price</code></td><td>Yes</td><td>Yes</td><td>&gt;= 0</td></tr><tr><td>Status</td><td>select</td><td><code>pln_status_code</code></td><td>Yes</td><td>Yes</td><td>1=Active, 0=Archived</td></tr></tbody></table><h3 id="actions-crud-3" tabindex="-1">Actions / CRUD <a class="header-anchor" href="#actions-crud-3" aria-label="Permalink to &quot;Actions / CRUD&quot;">​</a></h3><ul><li>[x] Create</li><li>[x] Read</li><li>[x] Update</li><li>[x] Delete (soft: set status to 0)</li><li>[ ] Special</li></ul><h3 id="related-selectors-modals-3" tabindex="-1">Related Selectors / Modals <a class="header-anchor" href="#related-selectors-modals-3" aria-label="Permalink to &quot;Related Selectors / Modals&quot;">​</a></h3><ul><li><strong>Menu module selector</strong>: (embedded or separate Plan-Menu Assignment screen) links <code>PlanMenu</code> entries to this plan.</li></ul><h3 id="permissions-3" tabindex="-1">Permissions <a class="header-anchor" href="#permissions-3" aria-label="Permalink to &quot;Permissions&quot;">​</a></h3><ul><li><strong>Module code</strong>: <code>SYS-001</code> (inferred — super admin)</li><li><strong>Minimum role permissions</strong>: write (full CRUD)</li><li><strong>Special rules</strong>: ONLY accessible to super admin accounts. API-key gated or admin-only auth. No RLS policies — the Supabase client used MUST have service_role or a custom admin JWT claim.</li></ul><h3 id="navigation-3" tabindex="-1">Navigation <a class="header-anchor" href="#navigation-3" aria-label="Permalink to &quot;Navigation&quot;">​</a></h3><ul><li><strong>Parent</strong>: System / Admin (menu group)</li><li><strong>Links to</strong>: Plan-Menu Assignment (child screen)</li></ul><h3 id="ux-pattern-3" tabindex="-1">UX Pattern <a class="header-anchor" href="#ux-pattern-3" aria-label="Permalink to &quot;UX Pattern&quot;">​</a></h3><p>List + Form (modal or page)</p><h3 id="business-rules-validations-3" tabindex="-1">Business Rules / Validations <a class="header-anchor" href="#business-rules-validations-3" aria-label="Permalink to &quot;Business Rules / Validations&quot;">​</a></h3><ul><li><code>pln_annual_price</code> SHOULD be less than <code>pln_monthly_price * 12</code> (annual discount).</li><li><code>pln_max_resources</code> MUST be &gt;= 0 or NULL; DB trigger enforces CHECK constraint.</li><li><code>pln_max_services</code> MUST be &gt;= 0 or NULL; DB trigger enforces CHECK constraint.</li><li>Setting status to 0 (archived) MUST NOT affect existing <code>OrganizationPlan</code> subscriptions — only prevents new subscriptions.</li><li>Deleting a plan with active <code>OrganizationPlan</code> rows MUST be blocked (foreign key or application check).</li><li>Plan limits are enforced via DB triggers at INSERT time on Employee, Service, Resource, and ClientOrganization tables.</li><li>At least ONE plan MUST exist and be active for the system to be usable in onboarding.</li></ul><h3 id="notes-3" tabindex="-1">Notes <a class="header-anchor" href="#notes-3" aria-label="Permalink to &quot;Notes&quot;">​</a></h3><p>This is a back-office screen, not part of the tenant-facing app. Consider building it as a separate admin panel or a protected route with a super-admin flag. The plan&#39;s <code>pln_currency_code</code> affects how prices display but not the operational currency of tenants (each org has its own currency).</p><hr><h2 id="screen-plan-menu-assignment" tabindex="-1">Screen: Plan-Menu Assignment <a class="header-anchor" href="#screen-plan-menu-assignment" aria-label="Permalink to &quot;Screen: Plan-Menu Assignment&quot;">​</a></h2><h3 id="route-4" tabindex="-1">Route <a class="header-anchor" href="#route-4" aria-label="Permalink to &quot;Route&quot;">​</a></h3><p><code>/admin/plans/:planId/menus</code></p><h3 id="purpose-4" tabindex="-1">Purpose <a class="header-anchor" href="#purpose-4" aria-label="Permalink to &quot;Purpose&quot;">​</a></h3><p>Toggle which <code>SystemMenu</code> modules a subscription plan unlocks. This is the feature flag engine — if a module is not in <code>PlanMenu</code>, no tenant on that plan can access it at the DB level.</p><h3 id="data-source-4" tabindex="-1">Data Source <a class="header-anchor" href="#data-source-4" aria-label="Permalink to &quot;Data Source&quot;">​</a></h3><ul><li><strong>Table(s)</strong>: <code>PlanMenu</code>, <code>SystemMenu</code></li><li><strong>RLS Context</strong>: No RLS — same super-admin access as Plan Management.</li></ul><h3 id="fields-4" tabindex="-1">Fields <a class="header-anchor" href="#fields-4" aria-label="Permalink to &quot;Fields&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Source</th><th>Required</th><th>Editable</th><th>Notes</th></tr></thead><tbody><tr><td>Plan Name</td><td>text (read-only)</td><td><code>Plan.pln_name</code></td><td>N/A</td><td>No</td><td>Header showing current plan</td></tr><tr><td>Module Name</td><td>text</td><td><code>SystemMenu.sys_menu_name</code></td><td>N/A</td><td>No</td><td>Displayed as tree node</td></tr><tr><td>Module Path</td><td>text</td><td><code>SystemMenu.sys_menu_path</code></td><td>N/A</td><td>No</td><td>Router path, helps identify module</td></tr><tr><td>Module Transaction Code</td><td>text</td><td><code>SystemMenu.sys_menu_transaction_code</code></td><td>N/A</td><td>No</td><td>e.g., &quot;FIN-001&quot;</td></tr><tr><td>Enabled</td><td>checkbox</td><td><code>PlanMenu</code> (if row exists)</td><td>N/A</td><td>No</td><td>Checked = plan has access to this module</td></tr></tbody></table><h3 id="actions-crud-4" tabindex="-1">Actions / CRUD <a class="header-anchor" href="#actions-crud-4" aria-label="Permalink to &quot;Actions / CRUD&quot;">​</a></h3><ul><li>[x] Create (link plan to menu module)</li><li>[x] Read (list all modules with enabled status)</li><li>[x] Update (toggle enabled/disabled)</li><li>[x] Delete (remove plan-module link)</li><li>[ ] Special</li></ul><h3 id="related-selectors-modals-4" tabindex="-1">Related Selectors / Modals <a class="header-anchor" href="#related-selectors-modals-4" aria-label="Permalink to &quot;Related Selectors / Modals&quot;">​</a></h3><ul><li><strong>SystemMenu tree selector</strong>: Renders the full <code>SystemMenu</code> hierarchy as a collapsible tree. Parent nodes can be toggled (auto-toggles all children). Transaction codes shown as badges.</li></ul><h3 id="permissions-4" tabindex="-1">Permissions <a class="header-anchor" href="#permissions-4" aria-label="Permalink to &quot;Permissions&quot;">​</a></h3><ul><li><strong>Module code</strong>: <code>SYS-001</code> (inferred — super admin)</li><li><strong>Minimum role permissions</strong>: write (full CRUD)</li><li><strong>Special rules</strong>: Same super-admin gating as Plan Management. Changes take effect immediately — existing tenants on this plan will gain/lose access on their next query.</li></ul><h3 id="navigation-4" tabindex="-1">Navigation <a class="header-anchor" href="#navigation-4" aria-label="Permalink to &quot;Navigation&quot;">​</a></h3><ul><li><strong>Parent</strong>: Plan Management (linked from plan list row or detail page)</li><li><strong>Links to</strong>: None</li></ul><h3 id="ux-pattern-4" tabindex="-1">UX Pattern <a class="header-anchor" href="#ux-pattern-4" aria-label="Permalink to &quot;UX Pattern&quot;">​</a></h3><p>Tree checkbox matrix (Plan × Module)</p><h3 id="business-rules-validations-4" tabindex="-1">Business Rules / Validations <a class="header-anchor" href="#business-rules-validations-4" aria-label="Permalink to &quot;Business Rules / Validations&quot;">​</a></h3><ul><li>Deleting a <code>PlanMenu</code> row immediately revokes access to that module for ALL tenants on this plan (DB-enforced via RLS policy that checks <code>PlanMenu</code>).</li><li>Adding a <code>PlanMenu</code> row immediately grants access.</li><li>If a parent <code>SystemMenu</code> node is not enabled, children SHOULD be visually disabled (uncheckable) or the parent must be enabled first.</li><li>The default Admin role onboarding grants ALL active modules — <code>PlanMenu</code> is the gating layer BEFORE <code>OrganizationRoleMenu</code>.</li><li>Changes MUST be confirmed with a warning: &quot;This will affect ALL tenants on this plan.&quot;</li></ul><h3 id="notes-4" tabindex="-1">Notes <a class="header-anchor" href="#notes-4" aria-label="Permalink to &quot;Notes&quot;">​</a></h3><p>This is the most critical gating screen. Every <code>OrganizationRoleMenu</code> check at the DB level starts by confirming the module exists in <code>PlanMenu</code> for the tenant&#39;s plan. Consider adding a &quot;review impact&quot; button that shows how many active tenants would be affected by a change. The tree should mirror the <code>SystemMenu</code> hierarchy exactly (parent → child → grandchild structure with <code>sys_menu_level</code> and <code>sys_menu_parent_id</code>).</p>',120)])])}const p=t(i,[["render",r]]);export{m as __pageData,p as default};
